# Analysis & Implementation Plan

I'll help you refactor the workspace creation flow to use full-page navigation instead of a modal. This requires:

1. **Navigation Logic**: Hide `WorkspacesList` and show `WorkspaceCreate` in full space
2. **State Management**: Track creation mode in parent component
3. **Component Restructuring**: Ensure `WorkspaceCreate` fills available space properly
4. **UX Flow**: Add clear back/cancel navigation

Let me implement this:

---

## 1. Update WorkspacesManager (Parent Container)

```vue client/src/components/workspaces/WorkspacesManager.vue
<script setup>
import WorkspacesList from './WorkspacesList.vue'
import WorkspaceCreate from './WorkspaceCreate.vue'
</script>

<template>
  <div class="w-full h-full flex flex-col">
    <WorkspacesList 
      v-if="!isCreating"
      :project="project"
      @create="isCreating = true"
    />
    <WorkspaceCreate 
      v-else
      :project="project"
      @close="isCreating = false"
      @created="handleWorkspaceCreated"
    />
  </div>
</template>

<script>
export default {
  props: ['project'],
  data() {
    return {
      isCreating: false
    }
  },
  methods: {
    handleWorkspaceCreated(workspace) {
      this.isCreating = false
      // Refresh list or emit event to parent
      this.$emit('workspace-created', workspace)
    }
  }
}
</script>
```

---

## 2. Refactor WorkspaceCreate (Full-Page Layout)

```vue client/src/components/workspaces/WorkspaceCreate.vue
<script setup>
import WorkspaceCreateSidebar from './WorkspaceCreateSidebar.vue'
import WorkspaceCreateContent from './WorkspaceCreateContent.vue'
</script>

<template>
  <div class="w-full h-full flex flex-col bg-base-100">

    <!-- Header Bar (Fixed, Sticky) -->
    <div class="flex items-center justify-between px-6 py-4 border-b border-base-200 bg-base-100 shrink-0">
      <div class="flex items-center gap-3">
        <button 
          class="btn btn-ghost btn-sm btn-circle"
          @click="$emit('close')"
          title="Back to workspaces"
        >
          <i class="fa-solid fa-arrow-left"></i>
        </button>
        <div class="w-10 h-10 rounded-lg bg-primary/10 text-primary flex items-center justify-center">
          <i class="fa-solid fa-plus"></i>
        </div>
        <div>
          <h2 class="text-2xl font-bold">Create Workspace</h2>
          <p class="text-xs text-base-content/50">Configure your new development environment</p>
        </div>
      </div>
    </div>

    <!-- Main Layout: Sidebar + Content (Scrollable) -->
    <div class="flex-1 flex gap-0 overflow-hidden">

      <!-- Sidebar (Fixed, Scrollable Content) -->
      <WorkspaceCreateSidebar
        :form="form"
        :templates="templates"
        :active-section="activeSection"
        @select-section="activeSection = $event"
        @update-template="form.template = $event"
      />

      <!-- Content Panel (Scrollable) -->
      <WorkspaceCreateContent
        :form="form"
        :active-section="activeSection"
        :templates="templates"
        :selected-template="templates[form.template]"
        @update-form="updateForm"
      />

    </div>

    <!-- Footer Bar (Fixed) -->
    <div class="flex items-center justify-between px-6 py-4 border-t border-base-200 bg-base-100 shrink-0">
      <div class="flex gap-2">
        <button 
          class="btn btn-ghost btn-md"
          @click="$emit('close')"
        >
          <i class="fa-solid fa-arrow-left"></i>
          Back
        </button>
      </div>
      <div class="flex gap-3">
        <button 
          class="btn btn-ghost btn-md"
          @click="resetForm"
        >
          Reset
        </button>
        <button
          class="btn btn-primary btn-md gap-2"
          :disabled="!isFormValid || isCreating"
          @click="createWorkspace"
        >
          <span v-if="isCreating" class="loading loading-spinner loading-sm"></span>
          <i v-else class="fa-solid fa-check"></i>
          Create Workspace
        </button>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  props: ['project'],
  emits: ['close', 'created'],
  data() {
    return {
      activeSection: 'basic',
      isCreating: false,
      templates: {
        'static-site': {
          id: 'static-site',
          name: 'Static Site',
          icon: 'fa-globe',
          description: 'Single container running a web site / dev server (e.g., Vue, React, Next.js)',
          details: 'Perfect for frontend projects. Includes Node.js, npm, and a dev server. No Docker-in-Docker support.',
          color: 'info'
        },
        'dev-stack': {
          id: 'dev-stack',
          name: 'Full-Stack Dev',
          icon: 'fa-cube',
          description: 'Sysbox container with systemd + inner Docker for full-stack development',
          details: 'Advanced environment with systemd and Docker daemon. Ideal for microservices, backend testing, and multi-container apps.',
          color: 'warning'
        },
        'custom': {
          id: 'custom',
          name: 'Custom',
          icon: 'fa-wrench',
          description: 'Empty workspace, admin provides all files',
          details: 'Blank slate. You define the entire docker-compose.yaml, Dockerfile, and runtime configuration.',
          color: 'secondary'
        }
      },
      form: {
        name: '',
        description: '',
        folder_path: '',
        template: 'static-site',
        project_ids: [],
        user_ids: [],
        apps: [{
          name: 'App',
          icon: 'fa-globe',
          path: '/app',
          port: 3000,
          roles: ['admin'],
          is_vnc: false,
          scheme: 'http'
        }],
        resources: {
          cpus: '',
          memory: '',
          shm_size: '512m'
        },
        use_sysbox: false
      }
    }
  },
  computed: {
    isFormValid() {
      return this.form.name && this.form.folder_path && this.form.template
    }
  },
  methods: {
    updateForm(updates) {
      Object.assign(this.form, updates)
    },
    resetForm() {
      this.form = {
        name: '',
        description: '',
        folder_path: '',
        template: 'static-site',
        project_ids: [],
        user_ids: [],
        apps: [{
          name: 'App',
          icon: 'fa-globe',
          path: '/app',
          port: 3000,
          roles: ['admin'],
          is_vnc: false,
          scheme: 'http'
        }],
        resources: {
          cpus: '',
          memory: '',
          shm_size: '512m'
        },
        use_sysbox: false
      }
      this.activeSection = 'basic'
    },
    async createWorkspace() {
      if (!this.isFormValid) return
      this.isCreating = true
      try {
        const workspace = await this.project.$api.workspaces.create({
          ...this.form,
          status: 'stopped'
        })
        this.$emit('created', workspace)
      } catch (error) {
        alert(`Failed: ${error.message}`)
      } finally {
        this.isCreating = false
      }
    }
  }
}
</script>
```

