## 3. Update WorkspacesList (Add Create Button)

```vue client/src/components/workspaces/WorkspacesList.vue
<script setup>
// Assuming this component exists and displays workspace cards
</script>

<template>
  <div class="w-full h-full flex flex-col">

    <!-- Header with Create Button -->
    <div class="flex items-center justify-between px-6 py-4 border-b border-base-200 bg-base-100 shrink-0">
      <div>
        <h2 class="text-2xl font-bold">Workspaces</h2>
        <p class="text-sm text-base-content/50">Manage your development environments</p>
      </div>
      <button 
        class="btn btn-primary gap-2"
        @click="$emit('create')"
      >
        <i class="fa-solid fa-plus"></i>
        New Workspace
      </button>
    </div>

    <!-- Workspaces Grid (Scrollable) -->
    <div class="flex-1 overflow-y-auto p-6">
      <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        <WorkspaceCard 
          v-for="workspace in workspaces"
          :key="workspace.id"
          :workspace="workspace"
          :project="project"
          @select="selectWorkspace"
          @edit="editWorkspace"
          @delete="deleteWorkspace"
          @start="startWorkspace"
          @stop="stopWorkspace"
        />
      </div>

      <div v-if="!workspaces.length" class="flex items-center justify-center h-64">
        <div class="text-center">
          <i class="fa-solid fa-inbox text-6xl text-base-content/20 mb-4"></i>
          <p class="text-lg text-base-content/50 mb-4">No workspaces yet</p>
          <button 
            class="btn btn-primary gap-2"
            @click="$emit('create')"
          >
            <i class="fa-solid fa-plus"></i>
            Create your first workspace
          </button>
        </div>
      </div>
    </div>

    <!-- Modals for Edit, Logs, etc. (keep existing modals) -->
    <WorkspaceLogs 
      v-if="selectedLogs"
      :workspace="selectedLogs"
      :project="project"
      @close="selectedLogs = null"
    />

    <WorkspaceSettings 
      v-if="selectedEdit"
      :workspace="selectedEdit"
      :available-projects="projects"
      @close="selectedEdit = null"
      @save="updateWorkspace"
      @delete="deleteWorkspace"
    />
  </div>
</template>

<script>
import WorkspaceCard from './WorkspaceCard.vue'
import WorkspaceLogs from './WorkspaceLogs.vue'
import WorkspaceSettings from './WorkspaceSettings.vue'

export default {
  components: { WorkspaceCard, WorkspaceLogs, WorkspaceSettings },
  props: ['project'],
  emits: ['create'],
  data() {
    return {
      workspaces: [],
      projects: [],
      selectedEdit: null,
      selectedLogs: null,
      isLoading: false
    }
  },
  async mounted() {
    await this.loadWorkspaces()
    await this.loadProjects()
  },
  methods: {
    async loadWorkspaces() {
      try {
        this.workspaces = await this.project.$api.workspaces.list()
      } catch (error) {
        console.error('Failed to load workspaces', error)
      }
    },
    async loadProjects() {
      try {
        this.projects = await this.project.$api.projects.list()
      } catch (error) {
        console.error('Failed to load projects', error)
      }
    },
    selectWorkspace(workspace) {
      // Navigate to workspace detail or preview
    },
    editWorkspace(workspace) {
      this.selectedEdit = { ...workspace }
    },
    async updateWorkspace(workspace) {
      try {
        await this.project.$api.workspaces.update(workspace)
        await this.loadWorkspaces()
        this.selectedEdit = null
      } catch (error) {
        alert(`Failed to update: ${error.message}`)
      }
    },
    async deleteWorkspace(workspaceId) {
      if (!confirm('Are you sure you want to delete this workspace?')) return
      try {
        await this.project.$api.workspaces.delete(workspaceId)
        await this.loadWorkspaces()
      } catch (error) {
        alert(`Failed to delete: ${error.message}`)
      }
    },
    async startWorkspace(workspaceId) {
      try {
        await this.project.$api.workspaces.lifecycle.start(workspaceId)
        await this.loadWorkspaces()
      } catch (error) {
        alert(`Failed to start: ${error.message}`)
      }
    },
    async stopWorkspace(workspaceId) {
      try {
        await this.project.$api.workspaces.lifecycle.stop(workspaceId)
        await this.loadWorkspaces()
      } catch (error) {
        alert(`Failed to stop: ${error.message}`)
      }
    }
  }
}
</script>
```

